	plan, err := task.AdmittedPlan()
	if err != nil || plan == nil {
		return false
	}
	if len(plan.Execution.Members) > 0 {
		return workspaceGreenhouseFullPipelinePlan(task, cfg)
	}
	return taskUsesGreenhouseReviewProvider(task, cfg, "") && fullPipelineSelected(task, "")
}

